session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_login();$uid=$_SESSION['user']['id'];$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM trips WHERE id=? AND owner_id=?');$st->execute([$id,$uid]);$trip=$st->fetch();if(!$trip){http_response_code(404);exit('Trip not found');}$destinations=$pdo->query('SELECT id,name FROM destinations WHERE is_active=1 ORDER BY name')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$destinationId=(int)($_POST['destination_id']??0);$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$budget=(float)($_POST['budget']??0);$desc=trim($_POST['description']??'');$q=$pdo->prepare('SELECT id,name FROM destinations WHERE id=? AND is_active=1');$q->execute([$destinationId]);$dest=$q->fetch();if(!$name||!$destinationId||!$start||!$end||$budget<0)$error='Vui lòng nhập đầy đủ thông tin.';elseif(!$dest)$error='Điểm đến không hợp lệ.';elseif($end<$start)$error='Ngày kết thúc phải sau ngày bắt đầu.';if(!$error){$pdo->prepare('UPDATE trips SET name=?,destination_id=?,destination=?,start_date=?,end_date=?,budget=?,description=? WHERE id=? AND owner_id=?')->execute([$name,$dest['id'],$dest['name'],$start,$end,$budget,$desc,$id,$uid]);flash('success','Đã cập nhật chuyến đi.');redirect('user/trip-detail.php?id='.$id);}}
$pageTitle='Chỉnh sửa chuyến đi';include __DIR__.'/../includes/header.php';show_flash();$selected=(int)($trip['destination_id']??0);
?><div class="page-shell"><div class="form-shell"><div class="eyebrow">EDIT TRIP</div><h1 class="page-title mt-1">Chỉnh sửa chuyến đi</h1><?php if($error): ?><div class="alert alert-danger mt-3"><?= e($error) ?></div><?php endif; ?><form method="post" class="row g-3 mt-2"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="col-md-8"><label class="form-label fw-semibold">Tên chuyến đi</label><input class="form-control" name="name" value="<?= e($trip['name']) ?>" required></div><div class="col-md-4"><label class="form-label fw-semibold">Điểm đến</label><select class="form-select" name="destination_id" required><?php foreach($destinations as $d): ?><option value="<?= $d['id'] ?>" <?= $selected===(int)$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Ngày bắt đầu</label><input class="form-control" type="date" name="start_date" value="<?= e($trip['start_date']) ?>" required></div><div class="col-md-4"><label class="form-label">Ngày kết thúc</label><input class="form-control" type="date" name="end_date" value="<?= e($trip['end_date']) ?>" required></div><div class="col-md-4"><label class="form-label">Ngân sách</label><input class="form-control" type="number" min="0" name="budget" value="<?= e($trip['budget']) ?>" required></div><div class="col-12"><label class="form-label">Mô tả</label><textarea class="form-control" rows="4" name="description"><?= e($trip['description']) ?></textarea></div><div class="col-12"><button class="btn btn-primary">Lưu thay đổi</button> <a class="btn btn-light border" href="<?= base_url('user/trip-detail.php?id='.$id) ?>">Hủy</a></div></form></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
